-- BJ001: 小石榴 — 8个月 男孩 中华田园犬，染成虎皮卷模样投奔领养中心
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ001', '小石榴', 'DOG', 'MALE', 'MEDIUM', 0, 'https://www.pohome.cn/upload/img/pet/avatar/large/214747561933415816.jpeg', 0, '北京', 1, '小石榴，2025年10月7日，在我们给领养中心的狗狗们举办集体生日拍照的时候，突然出现在院门口，开大门的同时，小小一个被染了色，像极了虎皮卷成精的它就跑了进来。目前已经完成免疫，正式进入领养中心找妈妈！', '<p>可爱的小石榴找妈妈，欢迎北京地区的领养人来预约见面哦~</p><p>小石榴性格非常活泼、亲人，互动方式有点儿另类，喜欢欲拒还迎和追球叼鞋游戏。</p><p>请看刚救助时的小石榴，像极了"虎皮卷成精"！</p><img src="/uploads/animals/67fbf80c-c48f-4d43-be65-b1e875b40b2d.jpeg"><p>去医院检查身体，好消息，没有传染病，坏消息，肚里有虫。直接住院驱虫+隔离观察，等待打疫苗，那时候的小石榴，也就刚刚断奶，眼睛上的蓝膜还没褪去。</p><img src="/uploads/animals/62f0554a-fea1-4760-ae66-34de76b56180.jpeg"><p>在医院，大家都很喜欢它，而且，这个颜色实在是太引人注目了，好多人都很好奇，真有长成这样的狗吗？</p><img src="/uploads/animals/ff232bf5-7229-4bff-9f4e-ee738c7562cb.jpeg"><p>经过1个月的等待，揭秘啦！它是辟邪小黑狗一枚。</p><p>没有买卖，就没有伤害！请别被不法狗贩子忽悠，哪有这样儿的小狗？！</p><img src="/uploads/animals/d813c923-4173-4c30-ab70-994aabadd16a.jpeg"><img src="/uploads/animals/475ae2cb-21b6-4829-86af-2acdb4484347.jpeg"><img src="/uploads/animals/bbf135dc-add1-4b75-b3f6-5657863189d5.jpeg"><img src="/uploads/animals/8180072d-6d27-4812-95e0-1c8c02a51e24.jpeg"><img src="/uploads/animals/e24f9ecc-0b86-4948-9a9b-e2f736295def.jpeg"><img src="/uploads/animals/09b06854-a82d-448a-a88e-c1d54c2af724.jpeg"><img src="/uploads/animals/fd9eb366-3053-42a7-8ae9-be8d47913b96.jpeg"><img src="/uploads/animals/aeeb943d-0f2b-4dc3-b355-5e64bdebcee9.jpeg"><p>小石榴爱玩，会用纸尿垫，不踩屎，喜欢猫（但猫都不喜欢小鼻嘎）。因为打疫苗期间一直没怎么外出，所以现在出门略怂，需要亲爱的爸爸妈妈带它多出门长长见识。</p><p>未来的体型大概是偏小一点点的中型犬，但如果让它吃很多，也许就是中型犬了~</p><p>希望您家可以上狗证，有时间陪它互动，慢慢长大，一起看世界！</p><img src="/uploads/animals/8182ab12-6068-4ee9-b8fe-335cd7f79112.jpeg">', '北京市房山区良乡领养中心', 39.9042, 116.4074);

-- BJ002: 牛牛 — 3岁 女孩 英国斗牛犬，门头沟救助的皮肤病康复犬
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ002', '牛牛', 'DOG', 'FEMALE', 'MEDIUM', 3, 'https://www.pohome.cn/upload/img/pet/avatar/large/191732456504166946.jpeg', 0, '北京', 1, '牛牛目前身体健康，暂未绝育、未免疫。能吃能睡，没心没肺，热情活泼，睡觉打呼噜，性格比较倔强。', '<p>牛牛未在领养中心生活，以下是来自救助人芥末的介绍：</p><p>牛牛是2022年平安夜圣诞节期间在门头沟一个村里救助的，当时它皮肤病严重，在街头流浪，于心不忍就救了它。</p><img src="/uploads/animals/b0f9a600-6ee9-45de-8a69-498a8d51b4da.jpeg"><p>经过治疗，牛牛的皮肤病已经痊愈。</p><p>它很可爱，我们希望给它找个了解英国斗牛犬、有一定养宠经验的主人。希望您全家同意领养，不笼养、不散养。去新家之前需要做完绝育。</p><img src="/uploads/animals/45a4e24b-0a99-48d9-b7d3-20c3fc81bfa6.jpeg"><img src="/uploads/animals/63177bcf-ed28-40dd-a400-49e497bc7355.jpeg">', '北京市门头沟区某村', 39.9042, 116.4074);

-- BJ003: 大灰灰 — 5岁 女孩 巨型贵宾犬，屠宰场救出的时尚封面模特
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ003', '大灰灰', 'DOG', 'FEMALE', 'LARGE', 5, 'https://www.pohome.cn/upload/img/pet/avatar/large/190131108137404425.jpeg', 1, '北京', 1, '大灰灰，灰色巨型贵宾犬，友好亲人，不属于特别活泼好动型，平时比较冷静，但见到陌生狗狗会叫，嗓门儿不小。已绝育，已免疫，身体健康！目前18.5公斤', '<p>大灰灰，女孩，2岁，灰色巨贵。目前正在住院，已完成全套体检、洗澡、体内外驱虫、绝育、打了第一针疫苗。来的时候就被剃了毛，所以外出要穿个小羽绒背心保暖。出院后将入住领养中心，并开放领养，北京地区，免费领养。</p><img src="/uploads/animals/edcc44b2-255e-4e69-a8d3-b1e25166f375.jpeg"><p>大灰灰来自河北，救助于屠宰场。</p><p>它性格挺好的，拴上狗链就能跟人走，不吵不闹，但不适应住笼子，进入家庭需要重新磨合外出上厕所等家庭生活习惯。见到陌生的狗狗（特别是不太友好的狗狗）会叫，嗓门儿比较大，请考虑邻居们是否能接受。</p><img src="/uploads/animals/25a91533-9f08-4604-9a85-e711adf93a5e.jpeg"><p>经过体检，大灰灰身体健康，已绝育、已体内外驱虫、目前完成了免疫第一针。</p><p>北京地区免费领养，需要能上狗证，科学喂养，有病看病。巨型贵宾属于大型犬，五环内很难上狗证，而且一辈子十几年会经历很多苦难，请一定要提前考虑好您未来10年是否能一直与它共同生活，无论贫穷与富有，无论疾病与健康，一辈子不离不弃！</p><img src="/uploads/animals/ac334140-df49-462a-bf76-0cc8f3f12f74.jpeg"><img src="/uploads/animals/1adec253-05de-46d2-b96f-3d7244a5551b.jpeg"><img src="/uploads/animals/1360a415-1845-41c4-a471-f3ef0fb49d8a.jpeg"><p>入住领养中心后，大灰灰越来越漂亮了，还成为了《1626》时尚杂志的封面模特呢~</p><img src="/uploads/animals/e049e805-d7a4-4595-badf-875fab84daab.jpeg"><img src="/uploads/animals/a6c24949-926f-4b77-bf62-032d8bed039f.jpeg">', '北京市房山区良乡领养中心', 39.9042, 116.4074);

-- BJ004: 小智 — 6岁 男孩 斯坦福犬，屠宰场救出，已绝育的温柔大男孩
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ004', '小智', 'DOG', 'MALE', 'MEDIUM', 6, 'https://www.pohome.cn/upload/img/pet/avatar/large/190130952626505731.jpeg', 1, '北京', 1, '小智，黑白双色斯坦福犬，国内好像并不多见呢！特别友好亲人，中型犬，爱吃爱玩，不认生，已绝育、已免疫，推荐领养。', '<img src="/uploads/animals/b5451f03-00d7-4066-be4f-9424d5fb554c.jpeg"><p>小智，男孩，3岁左右，超萌超可爱！活泼友好，爱吃爱晒太阳。</p><img src="/uploads/animals/b02ce38a-0411-4c73-bc9e-69dc4845506f.jpeg"><p>经过住院全套体检、洗澡、体内外驱虫、绝育、免疫。有些营养不良，瘦！出院后入住汪喵领养中心，开放领养，北京地区免费领养。</p><img src="/uploads/animals/06564b9f-85a3-476b-95bf-ed3145a43973.jpeg"><p>小智来自河北，救助于屠宰场。</p><p>小智以前一定是有家有主人的，因为到医院做体检时发现它已经完成绝育手术了。可惜，不知道是被遗弃了还是走丢了，反正它曾经离死亡非常近。但这些过往完全没有影响小智对人类的信任和亲近，所有人都可以跟小智亲亲抱抱举高高！</p><img src="/uploads/animals/8fdc5cf7-9540-40f8-ba46-5348f7334daf.jpeg"><p>小智已经完成体检，身体健康，已绝育、已体内外驱虫、目前完成了免疫第一针，暂时有些营养不良，目前17.5公斤。</p><p>北京地区免费领养，需要能上狗证，科学喂养，有病看病。斯坦福属于中型犬，以后它还会长得胖乎乎看起来一身肌肉的样子。</p><p>请您在领养之前一定要慎重考虑，一辈子十几年会经历很多事、遇到很多困难，您未来10年是否能一直与它共同生活呢？无论贫穷与富有，无论疾病与健康，一辈子不离不弃！</p><img src="/uploads/animals/e7b849b5-294c-4aed-a751-c3e3747676b1.jpeg"><img src="/uploads/animals/c61ba069-b358-4fb4-82b8-1ed1115af3f3.jpeg">', '北京市房山区良乡领养中心', 39.9042, 116.4074);

-- BJ005: LUCKY幸运 — 5岁 男孩 黑色巨型贵宾犬，屠宰场救出的"黑洞"美男子
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ005', 'LUCKY幸运', 'DOG', 'MALE', 'LARGE', 5, 'https://www.pohome.cn/upload/img/pet/avatar/large/190129771383359486.jpeg', 1, '北京', 1, 'Lucky，纯黑色巨型贵宾犬，友好亲人，比较胆小，到了陌生环境需要适应，毛量大，做个造型回头率超高！主人最好能抱得动它，如果Lucky感到害怕，会要求抱抱哦~已绝育、已免疫，对人对狗都很友好，25KG喽！巨贵属于中大型犬，五环内无法上狗证。', '<p>LUCKY，男孩，2岁，黑色巨贵</p><img src="/uploads/animals/8e2980d0-6dc4-42fe-9768-d65fa99189e3.jpeg"><img src="/uploads/animals/320e2663-5260-4f34-835b-a2a4e6feca2f.jpeg"><p>LUCKY，非常黑，堪比可以吸收光线的黑洞~经过住院全套体检、洗澡、体内外驱虫、绝育、免疫。出院后已经入住领养中心，开放领养，北京地区免费领养。</p><img src="/uploads/animals/1d4279d3-83bc-47ac-ad54-e9a845318b7f.jpeg"><p>LUCKY来自河北，救助于屠宰场。</p><p>相信LUCKY这么漂亮的狗狗曾经一定是有主人的，但不知道是被遗弃了还是走丢了，反正它曾经离死亡非常近。也许是被吓到了，LUCKY到了医院之后胆子很小，拴上牵引绳也不敢走，是大夫小哥哥抱着它走来走去的。样子是真的很萌，但体重也是真的挺重的。</p><p>LUCKY未来的主人可要锻炼身体哦~</p><img src="/uploads/animals/3b9f9951-9f06-43e0-99ea-8eff0034e899.jpeg"><p>LUCKY经过体检，身体健康，已绝育、已体内外驱虫、目前完成了免疫，身体健康，性格好！</p><p>北京地区免费领养，需要能上狗证，科学喂养，有病看病。</p><p>巨型贵宾属于大型犬，五环内很难上狗证，而且一辈子十几年会经历很多苦难，请一定要提前考虑好您未来10年是否能一直与它共同生活，无论贫穷与富有，无论疾病与健康，一辈子不离不弃！</p><img src="/uploads/animals/d60eb0a8-73db-4f62-ae84-2cc714537ad9.jpeg"><img src="/uploads/animals/d6f0f4cc-b9db-4fa6-97c9-a9412c9d3c87.jpeg">', '北京市房山区良乡领养中心', 39.9042, 116.4074);

