-- BJ006: 大宝 — 5岁 女孩 银虎斑猫，自来熟小棉袄，独生子女最佳
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ006', '大宝', 'CAT', 'FEMALE', 'SMALL', 5, 'https://www.pohome.cn/upload/img/pet/avatar/large/201495230654454469.jpeg', 1, '北京', 1, '大宝，是个性格特别特别亲人的银虎斑，女孩，已绝育，跟人类属于自来熟的性格，适应新环境很快，小骨架，目前还不到7斤，唯一的问题是不喜欢猫！建议带回家当独生子女，一定是个贴心小棉袄！', '<p>大宝，女孩，已绝育，性格迷人。</p><img src="/uploads/animals/4c4ae4d2-d25e-4dec-84a7-877fe753bf2e.jpeg"><p>大宝是个性格特别特别亲人的银虎斑，女孩，已绝育，身体健康，小骨架，目前还不到7斤。跟人类属于自来熟的性格，适应新环境很快，感觉是那种随遇而安的小猫咪。</p><img src="/uploads/animals/a45feec7-75fd-40be-a38c-e23181ee2645.jpeg"><p>大宝唯一的小问题就是不喜欢猫，也不能说不喜欢所有猫，可以共处一室，但不能狭路相逢面对面，建议带回家当独生子女吧，大宝一定是您的贴心小棉袄！</p><img src="/uploads/animals/7e66d763-06bb-4dfd-9139-21472e23b2d4.jpeg"><p>大宝平时很安静，不爱叫，不疯跑，也不爱扒拉东西，吃饭乖巧，一摸脑门儿就顶手，对所有人类都友好。</p><img src="/uploads/animals/d1bb0502-89a5-4409-8658-2360adcc0838.jpeg"><p>特别有意思的是，大宝有个小小的癖好，爱抱着自己的脚脚~特别逗！</p><img src="/uploads/animals/5d7c09f1-c064-4638-83eb-0797dc8dda5b.jpeg"><p>推荐领养！推荐领养！推荐领养！</p>', '北京市昌平区天通苑猫屋', 39.9042, 116.4074);

-- BJ007: 黑妞妞 — 4岁 女孩 玄猫，绝育手术感染后奇迹生还的温柔黑猫
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ007', '黑妞妞', 'CAT', 'FEMALE', 'SMALL', 4, 'https://www.pohome.cn/upload/img/pet/avatar/large/199975805666204005.jpeg', 1, '北京', 1, '黑妞妞是个流过浪、吃过苦、受过罪的可爱猫，性格亲人友好，喜欢贴贴，不喜欢被抱起来，生活习惯非常好，不拆不毁，身体健康，已免疫、已绝育，期待有缘人带回家做个暖心的小棉袄。推荐领养！北京地区免费领养！', '<p>小天使64号 黑妞妞（医院大夫给起的名字）</p><p>黑妞妞是2023年底来自北京某社区里进行TNR的流浪猫，性格温和又亲人，还会夹子音。据说它已经在那个小区流浪过一段时间了，还曾经生过一窝小黑娃。</p><img src="/uploads/animals/c53ffc33-cac6-451b-ac26-28f90d92dc8f.jpeg"><p>曾经流浪的黑妞妞没有名字，见人招呼它就会颠颠的跑出来。</p><img src="/uploads/animals/c1f95c84-7969-44d1-876b-634c32aebcd8.jpeg"><p>由于做绝育手术的医院术后护理不到位，导致它的伤口严重感染，发现时整个腹腔内都是脓液，内脏粘连，腹部皮肤坏死。</p><img src="/uploads/animals/be831f9d-6de9-45f1-baa1-ebea310d76d5.jpeg"><p>我们的志愿者连夜把黑妞妞转院到熟悉的宠物医院，夜里9点多院长赶回来进行了一场2个半小时的大手术，才把它抢救了回来。</p><img src="/uploads/animals/123e003a-6f74-4c68-8071-64ea3772b149.jpeg"><img src="/uploads/animals/ecfc6442-ae33-45c8-839a-2737e30856ba.png"><p>传说中的肠穿肚烂也不过如此，连天天做手术的大夫都说"太惨了！"做完手术的Ada非常虚弱，但它的乖巧懂事和温柔可爱让每个人都对它呵护备至。</p><img src="/uploads/animals/4a45c89b-2dba-4d22-9370-8e6e10850755.jpeg"><p>现在的黑妞妞已经满血复活，顺利融入汪喵大家庭，入住猫屋啦~</p><img src="/uploads/animals/a62c0b49-5afa-40d7-b9c8-9d4f92d3527c.jpeg"><p>我们一定要给可怜又可爱的黑妞妞找一个特别特别好的家，让它的下半生只有幸福，没有磨难。加油！</p>', '北京市昌平区天通苑猫屋', 39.9042, 116.4074);

-- BJ008: 面条 — 7岁 男孩 金吉拉，从一身铠甲到帅气长毛，猫屋男保姆
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ008', '面条', 'CAT', 'MALE', 'MEDIUM', 7, 'https://www.pohome.cn/upload/img/pet/avatar/large/195309458533126600.jpeg', 1, '北京', 1, '面条，已免疫、已绝育，身体健康，性格温顺亲人，喜欢照顾幼猫，爱玩球，会巡回小球，不喜欢成年公猫。面条的毛量非常大，很厚实，掉毛少，需要经常梳毛，扁脸猫的常见问题就是眼泪多，有泪痕，需要每天早晚给擦眼睛哦~', '<p>面条，已免疫、已绝育，身体健康，性格温顺亲人，喜欢照顾幼猫，爱玩球，会巡回小球，不喜欢成年公猫。</p><img src="/uploads/animals/d3a56ca7-14c1-4667-b1d0-3aac9733c01d.jpeg"><p>面条的毛量非常大，很厚实，掉毛少，需要经常梳毛，扁脸猫的常见问题就是眼泪多，有泪痕，需要每天早晚给擦眼睛哦~</p><img src="/uploads/animals/e1e12788-28cd-4b41-9acf-beb24d831676.jpeg"><p>面条从被救助时一身又脏又硬的铠甲，到住院后分3天才剃毛的光溜溜，再到皮肤恢复健康，开始长毛，但因为毛囊受损，有些地方毛长的特别慢，直到现在这么帅气，就差尾巴没有恢复好，可是费了我们不少心血呀，每天都得给面条擦脸，还不停的自责，怎么就擦不干净呢。。。</p><img src="/uploads/animals/cf56fc7a-c8ad-4c7b-bb58-358c4dfc1b59.jpeg"><img src="/uploads/animals/5805dbd5-7d3f-42df-b577-87e516a7a1df.jpeg"><p>面条刚进入模拟家庭-猫屋的时候，跟其他猫的相处并不太好，总是一幅要打架的样子，让我们深深的焦虑了一把，毕竟猫屋里的打架大王已经不少了~</p><p>万万没想到，面条入住没多久，猫屋里又来了2个小朋友——3个多月的奇奇和发发两兄弟，面条的父爱突然被激发了，化身老父亲、老大哥、男保姆，对小朋友呵护备至，陪它们玩，给它俩舔毛，教它俩狩猎，如果有其他猫路过，面条也会站在旁边守护。</p><img src="/uploads/animals/9a4cc0c1-7304-4ec1-9fd2-3c93952506d7.jpeg"><p>面条对人类的信任和友好不必多说，来过猫屋的人都知道，它的大脑袋是第一时间迎上去让人摸摸的。希望面条未来的家里没有成年猫（特别是成年大公猫）或狗（见过2次狗，开始比较激动，狗稳定猫就稳定，但没有过多接触），目前跟幼猫无障碍，很喜欢照顾小猫。</p><p>面条正在猫屋里等待领养，推荐哦~</p>', '北京市昌平区天通苑猫屋', 39.9042, 116.4074);

-- BJ009: 五仁儿 — 3岁 男孩 黄白花，从偷猫贼手中救下的宇宙无敌小可爱
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ009', '五仁儿', 'CAT', 'MALE', 'SMALL', 3, 'https://www.pohome.cn/upload/img/pet/avatar/large/196671564101194455.jpeg', 1, '北京', 1, '五仁儿是猫屋里最最亲人的小猫咪，小名"年年"，跟兄弟芝麻糊，小名"糊糊"（黏黏糊糊的谐音梗）一起来到猫屋，已免疫，已绝育。性格宇宙无敌可爱，推荐领养！', '<img src="/uploads/animals/85c87787-0717-477e-a280-8a05a8f10166.jpeg"><p>五仁儿是汪汪喵呜猫屋里最最亲人的小猫咪，小名"年年"，跟兄弟芝麻糊，小名"糊糊"（黏黏糊糊的谐音梗）一起入住猫屋，目前已完成2针免疫，已绝育。</p><p>让我们一起来看看五仁儿和芝麻糊两兄弟的救助故事吧！</p><h3>与偷猫贼抢时间</h3><p>是的，这并不是一个博眼球的标题党，而是真实情况。</p><img src="/uploads/animals/1bff0550-07f3-4ddc-b7b2-980b53dd4021.jpeg"><p>北京朝阳区某小区的6只小奶猫正在开心的追跑打闹，它们没有见过什么坏人，小区里有几个好心邻居为了让它们健康长大，每天早中晚都会排班下来喂食喂水，观察一下小猫的情况。在它们的妈妈不再寸步不离的看着它们，而是让小小猫们自己去闯世界后，邻居联系上汪汪喵呜，帮三花猫妈妈申请了免费绝育单，送去医院绝育了。</p><p>2023年8月30日（能记住这个日期完全是因为那天是中元节），晚归的邻居在22点多碰巧发现小猫生活区的马路边有个可疑人员，拿着大抄子和猫包，正在抓小猫，而最亲人的五仁儿首当其冲，已经被他塞进了猫包。当邻居质问这个小伙子是干什么的时候，他含含糊糊说是爱猫组织的，一通胡言乱语后，慌乱的扔下小猫骑车跑了。。。</p><img src="/uploads/animals/e2a81056-0075-4a96-a400-6c0b89e7d159.jpeg"><p>事后想想真是后怕，如果那天没人看到，没人多问几句，这几个可爱的小家伙儿将面对什么样的命运呢？</p><p>从那晚开始，十来位关心小猫的邻居组建了小区关爱猫咪群，每晚都有人在夜里去巡视一圈，以免这些不知人间险恶的小可爱惨遭毒手。夜里的五仁儿和芝麻糊对人类毫无戒心。</p><img src="/uploads/animals/21c8d3f9-bea9-4c3c-bd85-d90280368588.jpeg"><p>在我们了解具体情况后有点儿坐不住了。小猫和好心邻居没见过坏人，可汪喵的志愿者们见得多了。（咱不传播负能量，但亲人的小猫小狗在户外生存真的太难了，能闯关成功的并不多）。</p><p>于是，9月1日晚，我们出手了！</p><img src="/uploads/animals/b93825c9-63cc-4ee3-b614-97bfe226478e.jpeg"><p>跟邻居们商量了一下，鉴于汪喵的猫屋已经猫满为患，我们先带走最亲人也最危险的2小只，也就是黄白花的"五仁儿"和黑白奶牛"芝麻糊"。</p><img src="/uploads/animals/57235792-51d7-4fe3-8757-38ae6cb6319c.jpeg"><p>刚刚到医院的它俩，被安排住在一间豪华联排别墅里，为了有安全感，专门给加了个可以半遮蔽的纸箱子。芝麻糊胆子小，一直缩在五仁儿后边，一声不吭。</p><img src="/uploads/animals/cdd0c52a-456d-4fd8-b050-3631fd292ca3.jpeg"><p>而乖巧亲人，热情友好，眼神里透露着大学生的清澈的五仁儿同学，只用了5分钟，就从躲猫猫变成了求抱抱，饭也吃了，水也喝了，猫砂盆也用过了。</p><img src="/uploads/animals/1a4533c8-f475-4654-b66f-1dd735641a56.jpeg"><p>正是因为五仁儿的放松和陪伴，才让芝麻糊也慢慢的靠近陌生人，小哥俩真是互相支撑相亲相爱的一家人啊~</p><img src="/uploads/animals/0cbdd820-f56a-4f79-b629-6f70391dc063.jpeg"><p>1周后，经过体检、观察并顺利注射了第一针疫苗的五仁儿和芝麻糊顺利入住汪喵猫屋，成为了大HOUSE里的一员。这里有很多新朋友迎接它们。</p><img src="/uploads/animals/cef45cb5-73a2-47e0-8ee1-b667f6d2f6db.jpeg"><p>五仁儿的性格是极有猫德的，让亲亲抱抱举高高，如果你不主动，它会主动来找你，并不在乎认不认识，反正黏糊就对了~抱在身上的五仁儿有点儿不能控制自己，一不留神可能就会变身皮草大围脖，喜欢黏人小猫的领养人们，可以冲了！</p><img src="/uploads/animals/bb865be2-79eb-45a1-8a1c-8b723dfb30d2.jpeg"><img src="/uploads/animals/b710e023-544c-4c34-b168-3e4226e04d85.jpeg"><p>当然，出于对芝麻糊的关爱和我们的养猫建议，如果您想领养猫咪，可以考虑五仁儿和芝麻糊一起领，家里没人的时候小猫咪可以互相陪伴，互相玩耍，冬天还能一起抱团取暖。家里有人的时候，您也可以左拥右抱，家里超过2个人，也不会为了猫跟谁而闹矛盾，一人一只，公平公正~哈哈哈哈哈</p><img src="/uploads/animals/ba7e2a87-69bc-41ea-a3b1-8b69ec71d4c0.jpeg"><p>总而言之，五仁儿和芝麻糊是两只超可爱的小猫，也许长相平凡，但颜值不够，性格来凑，我们就是性格好！推荐领养！！</p><img src="/uploads/animals/c7b89c60-2bf9-497b-adea-252e941710ab.jpeg">', '北京市昌平区天通苑猫屋', 39.9042, 116.4074);

-- BJ010: 小绿 — 3岁 女孩 中华狸花猫，被怪人抓到楼顶后获救的幸运团宠
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ010', '小绿', 'CAT', 'FEMALE', 'SMALL', 3, 'https://www.pohome.cn/upload/img/pet/avatar/large/197143996897432443.jpeg', 1, '北京', 1, '小绿，是个性格很亲人的小猫，女孩，已绝育、已免疫，身体健康，适合家庭生活，喜欢跟同龄小猫玩。小绿和芝麻糊、五仁是一奶同胞，推荐领养哦~', '<img src="/uploads/animals/a1cb214f-d079-4777-91b3-a80018785ece.jpeg"><p>小绿，是个性格很亲人的小猫，女孩，已绝育，身体健康，适合家庭生活，喜欢跟同龄小猫玩。小绿和芝麻糊、五仁是一奶同胞，推荐领养哦~</p><img src="/uploads/animals/04bb5414-3610-4631-9a0b-d2e310c53213.jpeg"><p>2023年10月下旬，小区里的团宠之一"小绿"（其实人家小时候叫小狸）被莫名其妙的人抓到了楼顶，半夜被住在19层的邻居发现时，它正躲在楼道安全门的角落里瑟瑟发抖+嗷嗷叫，紧接着17层邻居接力，接它到自己家里暂住，然后汪汪喵呜孤儿院提供帮助，送它到宠物医院体检，治疗猫冠状病毒后，完成了猫生大事——绝育手术。目前正在医院康复，同时等待有缘人接它回家。</p>', '北京市朝阳区某小区', 39.9042, 116.4074);

